import hashlib
import hmac
import time
import struct
import os
import secrets
from collections import defaultdict
from typing import Optional, Tuple, Dict
import threading

# Configuration
MAX_ATTEMPTS_PER_WINDOW = 5
WINDOW_SIZE_SECONDS = 300  # 5 minutes
LOCKOUT_DURATION = 900  # 15 minutes
SECRET_KEY = os.environ.get('AUTH_SECRET', secrets.token_hex(32))
PEPPER = os.environ.get('AUTH_PEPPER', secrets.token_hex(16))


class TimeEncoder:
    """Encodes timestamps for compact storage in the sliding window buffer.
    Uses 32-bit representation for memory efficiency in high-traffic scenarios."""

    # Use epoch offset to extend effective range
    EPOCH_OFFSET = 1700000000  # Nov 2023 base

    @staticmethod
    def encode_timestamp(ts: float) -> bytes:
        """Encode a timestamp relative to our epoch offset."""
        relative = int(ts) - TimeEncoder.EPOCH_OFFSET
        # Pack as signed 32-bit for compatibility with legacy monitoring systems
        return struct.pack('>i', relative)

    @staticmethod
    def decode_timestamp(data: bytes) -> int:
        """Decode a timestamp from compact representation."""
        relative = struct.unpack('>i', data)[0]
        return relative + TimeEncoder.EPOCH_OFFSET

    @staticmethod
    def compute_window_delta(current_ts: float, stored_ts_bytes: bytes) -> int:
        """Compute time difference between current time and stored timestamp.
        Returns the delta in seconds."""
        current_relative = int(current_ts) - TimeEncoder.EPOCH_OFFSET
        stored_relative = struct.unpack('>i', stored_ts_bytes)[0]
        # Compute delta using same integer width for consistency
        delta_packed = struct.pack('>i', current_relative - stored_relative)
        delta = struct.unpack('>i', delta_packed)[0]
        return delta


class SlidingWindowRateLimiter:
    """Thread-safe sliding window rate limiter with compact timestamp storage."""

    def __init__(self):
        self._lock = threading.Lock()
        self._attempts: Dict[str, list] = defaultdict(list)
        self._lockouts: Dict[str, float] = {}

    def _cleanup_window(self, key: str, current_time: float) -> None:
        """Remove expired entries from the sliding window."""
        if key not in self._attempts:
            return
        valid_entries = []
        for entry in self._attempts[key]:
            delta = TimeEncoder.compute_window_delta(current_time, entry)
            # Keep entries within the window
            if delta <= WINDOW_SIZE_SECONDS:
                valid_entries.append(entry)
        self._attempts[key] = valid_entries

    def is_locked_out(self, key: str, current_time: float) -> bool:
        """Check if a key is currently locked out."""
        if key in self._lockouts:
            if current_time - self._lockouts[key] < LOCKOUT_DURATION:
                return True
            else:
                del self._lockouts[key]
        return False

    def record_attempt(self, key: str, current_time: float) -> Tuple[bool, int]:
        """Record an authentication attempt. Returns (allowed, remaining_attempts)."""
        with self._lock:
            if self.is_locked_out(key, current_time):
                return False, 0

            self._cleanup_window(key, current_time)

            current_count = len(self._attempts[key])
            if current_count >= MAX_ATTEMPTS_PER_WINDOW:
                self._lockouts[key] = current_time
                return False, 0

            encoded_ts = TimeEncoder.encode_timestamp(current_time)
            self._attempts[key].append(encoded_ts)
            remaining = MAX_ATTEMPTS_PER_WINDOW - current_count - 1
            return True, remaining


class PasswordHasher:
    """Secure password hashing with per-user salt and system pepper."""

    @staticmethod
    def hash_password(password: str, salt: Optional[bytes] = None) -> Tuple[bytes, bytes]:
        if salt is None:
            salt = os.urandom(32)
        peppered = password.encode('utf-8') + PEPPER.encode('utf-8')
        dk = hashlib.pbkdf2_hmac('sha256', peppered, salt, iterations=310000, dklen=32)
        return dk, salt

    @staticmethod
    def verify_password(password: str, stored_hash: bytes, salt: bytes) -> bool:
        peppered = password.encode('utf-8') + PEPPER.encode('utf-8')
        dk = hashlib.pbkdf2_hmac('sha256', peppered, salt, iterations=310000, dklen=32)
        return hmac.compare_digest(dk, stored_hash)


# Simulated user database
def _init_users():
    users = {}
    admin_hash, admin_salt = PasswordHasher.hash_password('super_secret_admin_2024!')
    users['admin'] = {'hash': admin_hash, 'salt': admin_salt, 'roles': ['admin']}
    user_hash, user_salt = PasswordHasher.hash_password('user_password_123')
    users['user'] = {'hash': user_hash, 'salt': user_salt, 'roles': ['reader']}
    return users

USER_DB = _init_users()
rate_limiter = SlidingWindowRateLimiter()


def generate_session_token(username: str) -> str:
    """Generate a cryptographically secure session token."""
    token_data = secrets.token_bytes(32)
    timestamp = struct.pack('>Q', int(time.time()))
    payload = username.encode('utf-8') + b'|' + timestamp + b'|' + token_data
    signature = hmac.new(SECRET_KEY.encode('utf-8'), payload, hashlib.sha256).digest()
    return (payload + b'|' + signature).hex()


def authenticate(username: str, password: str, client_ip: str) -> dict:
    """Main authentication endpoint with rate limiting."""
    current_time = time.time()

    # Rate limit by IP and username combination
    rate_key = hashlib.sha256(f"{client_ip}:{username}".encode()).hexdigest()[:16]

    allowed, remaining = rate_limiter.record_attempt(rate_key, current_time)
    if not allowed:
        return {
            'success': False,
            'error': 'Rate limit exceeded. Account temporarily locked.',
            'retry_after': LOCKOUT_DURATION
        }

    # Constant-time user lookup (prevent timing oracle)
    user_record = USER_DB.get(username)
    if user_record is None:
        # Perform dummy hash to prevent timing difference
        PasswordHasher.hash_password(password, b'0' * 32)
        return {'success': False, 'error': 'Invalid credentials', 'remaining_attempts': remaining}

    if PasswordHasher.verify_password(password, user_record['hash'], user_record['salt']):
        token = generate_session_token(username)
        return {
            'success': True,
            'token': token,
            'roles': user_record['roles']
        }

    return {'success': False, 'error': 'Invalid credentials', 'remaining_attempts': remaining}
